DECLARE @student_no varchar(15)=?,@student_name nvarchar(16)=?,@student_name_kana nvarchar(36)=?,@birth_date date=?,@gender_code varchar(1)=?,@postal_code varchar(7)=?,@prefecture_code varchar(2)=?,@address_line1 nvarchar(90)=?,@address_line2 nvarchar(90)=?,@phone_number varchar(16)=?,@email_address varchar(60)=?,@admission_date date=?,@enrollment_status_code varchar(2)=?,@enrollment_end_date date=?,@class_id bigint=?,@emergency_contact_name nvarchar(16)=?,@relationship_code varchar(2)=?,@emergency_phone_number varchar(16)=?,@remarks nvarchar(240)=?,@name_key nvarchar(320)=?,@kana_key nvarchar(36)=?,@actor nvarchar(128)=?,@now datetimeoffset(7)=?; DECLARE @changed TABLE(id bigint); DECLARE @id bigint=?,@version bigint=?; UPDATE dbo.m_student SET student_name=@student_name,student_name_kana=@student_name_kana,birth_date=@birth_date,gender_code=@gender_code,postal_code=@postal_code,prefecture_code=@prefecture_code,address_line1=@address_line1,address_line2=@address_line2,phone_number=@phone_number,email_address=@email_address,admission_date=@admission_date,enrollment_status_code=@enrollment_status_code,enrollment_end_date=@enrollment_end_date,class_id=@class_id,emergency_contact_name=@emergency_contact_name,relationship_code=@relationship_code,emergency_phone_number=@emergency_phone_number,remarks=@remarks,name_key=@name_key,kana_key=@kana_key,updated_at=@now,updated_by=@actor,row_version=row_version+1 OUTPUT INSERTED.student_id INTO @changed WHERE student_id=@id AND row_version=@version AND is_deleted=0; SELECT id FROM @changed;
